"""Generated by the NL to Flow Diagram Encoder Pipeline."""

class unnamed_class:
    def __init__(self):
        self.stack = []
        self.size = 0

    def push(self, x):
        self.stack.append(x)
        self.size = (self.size + 1)

    def pop(self):
        if (self.size > 0):
            self.size = (self.size - 1)
            return self.stack.pop()
        else:
            raise Exception('ERROR')

    def peek(self):
        if (self.size > 0):
            return self.stack[(self.size - 1)]
        else:
            raise Exception('ERROR')






# Example usage
s = unnamed_class()

s.push(10)
s.push(20)
s.push(30)

print(s.peek())   # 30
print(s.pop())    # 30
print(s.pop())    # 20
print(s.peek())   # 10
print(s.pop())    # 10

# This will raise an error
try:
    print(s.pop())
except Exception as e:
    print("Caught:", e)
